            aWandererC = aWandererC ^ (((RotL64(aPrevious, 51U) + RotL64(aOrbiterD, 53U)) + aOrbiterG) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 10U)) & S_SALT1]);
