            //
            aIngress = RotL64(aEarthLaneC[((aIndex + 28320U)) & S_BLOCK1], 22U) ^ RotL64(aEarthLaneA[((S_BLOCK1 - aIndex + 32289U)) & S_BLOCK1], 43U);
            aIngress = TwistMix64::DiffuseB(aIngress);
