            //
            aOrbiterD = ((aWandererF + RotL64(aPrevious, 14U)) + RotL64(aCarry, 35U)) + 0x58094BE2B812A4CAULL;
            aOrbiterK = (aWandererG + RotL64(aScatter, 3U)) + 0x540DB7EC9CCE7A46ULL;
            aOrbiterH = (aWandererH + RotL64(aIngress, 21U)) + 0x1C203DCD7C9EC23DULL;
            aOrbiterF = (aWandererE + RotL64(aCross, 57U)) + 0xF66EA45E2E477D89ULL;
            aOrbiterI = (aWandererC + RotL64(aScatter, 47U)) + 0x37239CBE3CFAB21EULL;
            aOrbiterA = ((aWandererA + RotL64(aCross, 52U)) + RotL64(aCarry, 47U)) + 0x6E77B546904B2322ULL;
            aOrbiterG = (((aWandererJ + RotL64(aIngress, 27U)) + RotL64(aCarry, 19U)) + 0xB34E19C59C7F25BAULL) + aTwistOrbiterAssignSaltD[((aIndex + 15U)) & S_SALT1];
            aOrbiterB = ((aWandererI + RotL64(aPrevious, 39U)) + 0x1543730354F070B7ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterJ = (aWandererB + RotL64(aScatter, 35U)) + 0x83ECAD68B4A47071ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterK) + 0xCC5883BDD715F0D3ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0xBDF9BC70FEC29811ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x487EF17469754EEDULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterI) + 0xF988551E230418EDULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterF) ^ 0xB46F13B380E6B766ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x379AE65CA37EA18DULL), 51U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xCBA436DA909B113EULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0x2BBEAC2CE6060D33ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x987071F25F1C3EC3ULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0xD1EDD44C97B12C57ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 29U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0xF3A6AE2BF5AD9277ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xBA2DA69144B1968DULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterD) + 0xFCAD95A0BCCDED92ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x584C1F1134BD16DDULL;
            aOrbiterB = RotL64((aOrbiterB * 0x24E7ADF5477A3F8BULL), 13U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x94FD99F7DBC65221ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x7DC39092F25291B9ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x1E6B6AB8D20BB1E5ULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0xFC8B31A148286719ULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1];
