            //
            aWandererJ = aWandererJ + ((RotL64(aScatter, 40U) + aOrbiterJ) + RotL64(aOrbiterI, 29U));
            aWandererA = aWandererA ^ (((RotL64(aCross, 53U) + RotL64(aOrbiterF, 53U)) + aOrbiterH) + aTwistWandererUpdateSaltE[((aIndex + 9U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aPrevious, 35U) + aOrbiterK) + RotL64(aOrbiterJ, 57U)) + RotL64(aCarry, 27U)) + aTwistWandererUpdateSaltD[((aIndex + 22U)) & S_SALT1]);
