            aIngress = (RotL64(aEarthLaneA[((aIndex + 678U)) & S_BLOCK1], 10U) ^ RotL64(aEarthLaneB[((aIndex + 230U)) & S_BLOCK1], 27U));
            aIngress ^= RotL64(pSnowLaneA[((S_BLOCK1 - aIndex + 4132U)) & S_BLOCK1], 19U);
