            //
            aOrbiterG = (aWandererK + RotL64(aPrevious, 35U)) + 0x79C72E15A1DAB54CULL;
            aOrbiterH = (aWandererB + RotL64(aIngress, 41U)) + 0xF4F0911E05C91D75ULL;
            aOrbiterF = ((aWandererA + RotL64(aCross, 47U)) + RotL64(aCarry, 41U)) + 0xBC9D4A0F54A2DD27ULL;
            aOrbiterA = ((aWandererE + RotL64(aScatter, 13U)) + RotL64(aCarry, 53U)) + 0x04A17C44DE41780FULL;
            aOrbiterJ = ((aWandererH + RotL64(aCross, 28U)) + 0x28B35125A55741D2ULL) + aTwistOrbiterAssignSaltE[((aIndex + 5U)) & S_SALT1];
            aOrbiterE = (((aWandererI + RotL64(aPrevious, 19U)) + RotL64(aCarry, 27U)) + 0xBC62D5ED05A23951ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterI = (aWandererG + RotL64(aIngress, 3U)) + 0x6AA66CBEFEC0B89CULL;
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0x51A612CD9C154D9FULL) + aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x8E27E2D9F4742106ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6D8EF662A995A0CDULL), 13U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x6CA89B359B14D1A8ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0x79E9416FDC3D2AD9ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xDD23DF4266BA81ABULL), 51U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x4F9CF76162834AC5ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0xF6D057C8953F9D41ULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x92B9D7B41A90F419ULL), 57U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xCFA5B70269EA4142ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0xC63F91BEA1BD06D6ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x74F959E13C8F3AA1ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0xD6141EA6387534C8ULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x4F882C6B5AF881EFULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 16U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xB7F2157CD04B436FULL), 5U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x6222A4971D32497EULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0x78E3EC284B9022EEULL;
            aOrbiterI = RotL64((aOrbiterI * 0x821D20BD4AB2D627ULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x51BE814C4E2999C6ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterI) ^ 0xBB8C33E92CC9B465ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xDA862BC0B69E9761ULL), 19U);
            //
            aIngress = RotL64(aOrbiterG, 37U) ^ aOrbiterA;
