            aWandererA = aWandererA + (((RotL64(aIngress, 13U) + aOrbiterA) + RotL64(aOrbiterJ, 3U)) + RotL64(aCarry, 47U));
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterH, 37U)) + aOrbiterG);
            aWandererG = aWandererG + (((RotL64(aCross, 5U) + aOrbiterI) + RotL64(aOrbiterH, 47U)) + RotL64(aCarry, 35U));
