            aWandererB = aWandererB ^ ((RotL64(aScatter, 3U) + aOrbiterH) + RotL64(aOrbiterB, 13U));
            aWandererD = aWandererD + ((RotL64(aCross, 47U) + RotL64(aOrbiterE, 29U)) + aOrbiterA);
            aWandererI = aWandererI ^ (((RotL64(aPrevious, 30U) + RotL64(aOrbiterA, 47U)) + aOrbiterK) + aKeyRotateAWandererUpdateSaltA[((aIndex + 28U)) & S_SALT1]);
            aWandererJ = aWandererJ + ((RotL64(aIngress, 51U) + aOrbiterF) + RotL64(aOrbiterK, 41U));
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 41U) + aOrbiterI) + RotL64(aOrbiterG, 20U)) + aKeyRotateAWandererUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1]);
