            aWandererB = aWandererB ^ ((RotL64(aScatter, 38U) + aOrbiterJ) + RotL64(aOrbiterH, 22U));
            aWandererH = aWandererH + ((RotL64(aPrevious, 21U) + RotL64(aOrbiterC, 51U)) + aOrbiterD);
            aWandererG = aWandererG ^ ((RotL64(aCross, 27U) + RotL64(aOrbiterK, 39U)) + aOrbiterA);
            //
