            aOrbiterC = (aWandererB + RotL64(aIngress, 26U)) + 0xEC4985ACF4D840B3ULL;
            aOrbiterG = (aWandererF + RotL64(aScatter, 39U)) + 0x9885A7D5828B66E1ULL;
            aOrbiterE = ((aWandererJ + RotL64(aIngress, 51U)) + RotL64(aCarry, 3U)) + 0x3C56230BF3D75EA9ULL;
            aOrbiterF = ((aWandererC + RotL64(aScatter, 11U)) + RotL64(aCarry, 57U)) + 0x0991D2CEA6071E12ULL;
            aOrbiterA = ((aWandererI + RotL64(aCross, 29U)) + RotL64(aCarry, 11U)) + 0xBB55534C4189BC61ULL;
            aOrbiterJ = ((aWandererH + RotL64(aPrevious, 5U)) + 0x0E2732ADAD88239BULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 17U)) & S_SALT1];
